import json
from pathlib import Path
out=Path('icon_set/work/nontext-sub-audit');data=json.loads((out/'results.json').read_text());s=data['summary']
page='''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Non-text sub icons · conversion check</title><style>body{font:15px system-ui;margin:24px;background:#f4f6f8;color:#24323c}p,li{line-height:1.6}h1{font-size:26px}input,select{padding:10px;margin:5px;font:inherit}article{padding:18px;margin:18px 0;background:white;border:1px solid #d5dfe5;border-radius:8px}small{color:#627480}.compare{display:flex;gap:36px;flex-wrap:wrap}.art{width:128px;height:128px;background:linear-gradient(#ccc4 1px,transparent 1px),linear-gradient(90deg,#ccc4 1px,transparent 1px);background-size:4px 4px}.native{display:block;width:32px;height:32px;margin:10px 0}.error{color:#b23628}.warning{color:#956014}button{font:inherit;padding:8px}a{color:#26728a}</style><h1>Non-text sub icons · conversion check</h1><p id="summary"></p><p>This is a read-only script audit of the saved exports. Text excluded. Checks: 32×32 canvas, 32-unit maximum ink extent, 4-unit round stroke, clipping, integer anchors/control points, integer arc radii, and source freshness.</p><p>Conversion warnings compare the current result with a proportional 32-ink version of the same source before grid snapping. Changes to connected parts or enclosed openings are rechecked at 16×. These warnings need visual inspection; they are not automatic design failures. An ink-mask difference above 20% is also flagged for review. No artwork or approvals were changed.</p><input id="search" placeholder="Search name"><select id="filter"><option value="flagged">All flagged</option><option value="errors">Measured rule failures</option><option value="warnings">Conversion warnings</option><option value="clear">No flags from this script</option><option value="all">All non-text artworks</option></select><p id="count"></p><button id="prev">Previous</button> <span id="page"></span> <button id="next">Next</button><div id="list"></div><script>const data=DATA;let page=0;const $=x=>document.getElementById(x),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const labels={fractional_radii:'Fractional arc radii',fractional_points:'Fractional path coordinates',clipping:'Ink outside canvas',ink_extent:'Maximum ink dimension is not 32',stroke_style:'Incorrect stroke style',canvas:'Incorrect canvas',stale_source:'Source changed since export',check_error:'Could not complete check',parts_or_openings_changed:'Connected parts or openings changed after snapping (confirmed at 16×)',raster_sensitive_detail:'Small details vary with raster size',large_ink_difference:'More than 20% difference in ink coverage',path_count_changed:'Path count changed'};const s=data.summary;$('summary').textContent=`${s.total} checked · ${s.basic_pass} pass basic rules · ${s.basic_fail} fail basic rules · ${s.needs_visual_review} have conversion warnings. Counts overlap.`;function render(){const f=$('filter').value,q=$('search').value.toLowerCase(),rs=data.rows.filter(r=>(r.name+' '+r.key).toLowerCase().includes(q)&&(f==='all'||f==='errors'&&r.errors.length||f==='warnings'&&r.warnings.length||f==='flagged'&&(r.errors.length||r.warnings.length)||f==='clear'&&!r.errors.length&&!r.warnings.length));const n=Math.max(1,Math.ceil(rs.length/20));page=Math.min(page,n-1);$('count').textContent=rs.length+' artworks';$('page').textContent=`${page+1} / ${n}`;$('prev').disabled=page===0;$('next').disabled=page===n-1;$('list').innerHTML=rs.slice(page*20,page*20+20).map(r=>`<article><h2>${esc(r.name)}</h2><small>${esc(r.key)}</small><ul>${r.errors.map(f=>'<li class="error">'+esc(labels[f]||f)+'</li>').join('')}${r.warnings.map(f=>'<li class="warning">'+esc(labels[f]||f)+'</li>').join('')}</ul>${r.exception?'<p>'+esc(r.exception)+'</p>':''}<div class="compare"><div><p>Proportional fit before snapping</p><img class="art" src="${r.before_uri||''}"><img class="native" src="${r.before_uri||''}"></div><div><p>Current 32-unit export</p><img class="art" src="${r.after_uri||''}"><img class="native" src="${r.after_uri||''}"></div></div><small>Ink bounds: ${r.ink_bounds?.map(x=>x.toFixed(2)).join(', ')} · ink coverage difference: ${(100*(r.ink_difference||0)).toFixed(1)}%</small>${r.off_grid_radii?'<details><summary>Off-grid radii evidence</summary><pre>'+esc(JSON.stringify(r.off_grid_radii,null,2))+'</pre></details>':''}</article>`).join('')}for(const x of ['search','filter'])$(x).oninput=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};render();</script></html>'''.replace('DATA',json.dumps(data).replace('</','<\\/'))
(out/'index.html').write_text(page);Path('icon_set/dist/gallery/nontext-sub-audit.html').write_text(page)
(out/'summary.md').write_text('# Non-text conversion checks\n\n'+json.dumps(s,indent=2)+'\n\nScript measurements only; conversion warnings require visual review. No assets changed.\n')
